(632219, 65460, 3087, '<td valign="top">A pretty macro with nice composition and nice use of shallow DOF. I love the blurred lines of the background and particularly the colours within them.</td>', 'A pretty macro with nice composition and nice use of shallow DOF. I love the blurred lines of the background and particularly the colours within them.', '2004-03-22 17:52:15.000000', NULL, 1),
(632223, 65890, 3087, '<td valign="top">A nicely composed image which would work well as a cover because of the obvious space for magazine title towards the top. The strong glare/ reflection on the metallic foreground is the main negative for me.</td>', 'A nicely composed image which would work well as a cover because of the obvious space for magazine title towards the top. The strong glare/ reflection on the metallic foreground is the main negative for me.', '2004-03-22 17:53:59.000000', NULL, 1),
