(633656, 65890, 9763, '<td valign="top">Is this Disney Hall?  It''s a bit grey.  Need more whites and blacks in the photo.  I think perhaps a brighter day or a longer exposure on an f22 aperature. :)</td>', 'Is this Disney Hall?  It''s a bit grey.  Need more whites and blacks in the photo.  I think perhaps a brighter day or a longer exposure on an f22 aperature. :)', '2004-03-23 14:50:12.000000', NULL, 1),
(633657, 65842, 9763, '<td valign="top">Contrast is a little high, but very nice composition and photo overall!</td>', 'Contrast is a little high, but very nice composition and photo overall!', '2004-03-23 14:51:23.000000', NULL, 1),
(633658, 65875, 9763, '<td valign="top">The levels are a bit high here, but this photo composition is amazing.  Great capture.  Try toning down the levels to add some more ''dark'' areas in.</td>', 'The levels are a bit high here, but this photo composition is amazing.  Great capture.  Try toning down the levels to add some more ''dark'' areas in.', '2004-03-23 14:52:19.000000', NULL, 1),
(633659, 65621, 9763, '<td valign="top">The bird blends a little too much with the background.  It''d be nice to have the bird clear and the rest of the photo with this filter effect.</td>', 'The bird blends a little too much with the background.  It''d be nice to have the bird clear and the rest of the photo with this filter effect.', '2004-03-23 14:53:00.000000', NULL, 1),
(633662, 65655, 11487, '<td valign="top">Very nicely done.  Looks just like a Time cover.  Plenty of room for text.</td>', 'Very nicely done.  Looks just like a Time cover.  Plenty of room for text.', '2004-03-23 14:53:33.000000', NULL, 1),
(633663, 65805, 9763, '<td valign="top">The angle of light is too harsh.  You need to tone down the light.  Also, the model is too shiney (clothes and face), needs more blur.  Background not popping enough... try yellow.  Eyes also not in focus.</td>', 'The angle of light is too harsh.  You need to tone down the light.  Also, the model is too shiney (clothes and face), needs more blur.  Background not popping enough... try yellow.  Eyes also not in focus.', '2004-03-23 14:54:03.000000', NULL, 1),
(633665, 65911, 9763, '<td valign="top">Way too dark.  The effect at the top is nice, but the building is too dark to appreciate</td>', 'Way too dark.  The effect at the top is nice, but the building is too dark to appreciate', '2004-03-23 14:54:29.000000', NULL, 1),
(633668, 65851, 9763, '<td valign="top">Food too bright, tone down the flash a bit.  Use candle light or various lamps to light the food from all angles.  Also, I''d use a 4.0 aperature or greater to help blur the background more.</td>', 'Food too bright, tone down the flash a bit.  Use candle light or various lamps to light the food from all angles.  Also, I''d use a 4.0 aperature or greater to help blur the background more.', '2004-03-23 14:55:45.000000', NULL, 1),
(633669, 65860, 9763, '<td valign="top">The netting is a little too bright.  I''d shorten the exposure time on this.</td>', 'The netting is a little too bright.  I''d shorten the exposure time on this.', '2004-03-23 14:56:13.000000', NULL, 1);
