(638128, 65720, 11897, '<td valign="top">I feel a closer crop on the two backpackers may improve this.</td>', 'I feel a closer crop on the two backpackers may improve this.', '2004-03-25 13:49:00.000000', NULL, 1),
(638129, 65916, 11897, '<td valign="top">Lovely picture, caught the eyes very well.</td>', 'Lovely picture, caught the eyes very well.', '2004-03-25 13:49:41.000000', NULL, 1),
