(638131, 65862, 11897, '<td valign="top">Good enough for any magazine cover. 9</td>', 'Good enough for any magazine cover. 9', '2004-03-25 13:50:46.000000', NULL, 1),
(638135, 65127, 11897, '<td valign="top">Very good shot, I would like to see a slightly closer focus and crop on the insect.<br/>maybe even just the single flowerhead group.<br/>still excellent.</td>', 'Very good shot, I would like to see a slightly closer focus and crop on the insect.maybe even just the single flowerhead group.still excellent.', '2004-03-25 13:52:23.000000', NULL, 1),
