(638149, 65853, 11897, '<td valign="top">lovely capture, pity it isn''t more facing the camera.</td>', 'lovely capture, pity it isn''t more facing the camera.', '2004-03-25 13:59:26.000000', NULL, 1),
(638155, 65668, 11897, '<td valign="top">Great composition but a little unsharp, smaller aperature would improve this.<br/>the lighting is pretty good.</td>', 'Great composition but a little unsharp, smaller aperature would improve this.the lighting is pretty good.', '2004-03-25 14:01:36.000000', NULL, 1),
