INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(638163, 65630, 11897, '<td valign="top">wonderful image.</td>', 'wonderful image.', '2004-03-25 14:04:08.000000', NULL, 1),
(638165, 65910, 11897, '<td valign="top">Very sharp, the red badge helps a lot, good luck.</td>', 'Very sharp, the red badge helps a lot, good luck.', '2004-03-25 14:04:53.000000', NULL, 1),
(638168, 65632, 11897, '<td valign="top">good enough to grace any magazine cover.</td>', 'good enough to grace any magazine cover.', '2004-03-25 14:05:36.000000', NULL, 1),
(638170, 65659, 11897, '<td valign="top">The background seems a little too bright, and I think the picture is crooked.</td>', 'The background seems a little too bright, and I think the picture is crooked.', '2004-03-25 14:06:32.000000', NULL, 1),
(638209, 65900, 6597, '<td valign="top">I would say that this is what I would expect to see on the cover of aBaseball digest 7</td>', 'I would say that this is what I would expect to see on the cover of aBaseball digest 7', '2004-03-25 14:29:47.000000', NULL, 1),
(638212, 65395, 6597, '<td valign="top">These are beautiful a goot shot    gets a 8 from me</td>', 'These are beautiful a goot shot    gets a 8 from me', '2004-03-25 14:31:23.000000', NULL, 1),
(638266, 65452, 11897, '<td valign="top">The waterfall is great but the background does nothing for this shot, not your fault I suppose but you chose this water feature,</td>', 'The waterfall is great but the background does nothing for this shot, not your fault I suppose but you chose this water feature,', '2004-03-25 15:21:02.000000', NULL, 1),
(638267, 65756, 11897, '<td valign="top">Fine picture but nothing special.</td>', 'Fine picture but nothing special.', '2004-03-25 15:21:35.000000', NULL, 1),
(638268, 64921, 11897, '<td valign="top">Good use of space, I like it very much.</td>', 'Good use of space, I like it very much.', '2004-03-25 15:22:08.000000', NULL, 1),
(638269, 65776, 11897, '<td valign="top">Great picture, should be in the ribbons.</td>', 'Great picture, should be in the ribbons.', '2004-03-25 15:22:50.000000', NULL, 1),
(638272, 65806, 11897, '<td valign="top">Slightly shadowy,<br/>probably the metering being fooled by the reflections.<br/>use of a polarizer required here to get rid of the reflections.</td>', 'Slightly shadowy,probably the metering being fooled by the reflections.use of a polarizer required here to get rid of the reflections.', '2004-03-25 15:24:34.000000', NULL, 1),
(638273, 65603, 11897, '<td valign="top">I think I am looking at a ribbon here<br/>Brilliant and well executed. 10</td>', 'I think I am looking at a ribbon hereBrilliant and well executed. 10', '2004-03-25 15:25:22.000000', NULL, 1),
(638274, 65434, 11897, '<td valign="top">good picture, but I feel the fountain isn''t just right.</td>', 'good picture, but I feel the fountain isn''t just right.', '2004-03-25 15:26:03.000000', NULL, 1),
(638276, 65893, 11897, '<td valign="top">great shot, great title.</td>', 'great shot, great title.', '2004-03-25 15:26:27.000000', NULL, 1),
(638277, 65761, 11897, '<td valign="top">A bit less foreground may look better, good picture though.</td>', 'A bit less foreground may look better, good picture though.', '2004-03-25 15:27:06.000000', NULL, 1),
(638279, 65848, 11897, '<td valign="top">I would try a little more contrast and saturation.</td>', 'I would try a little more contrast and saturation.', '2004-03-25 15:27:50.000000', NULL, 1),
(638280, 65767, 11897, '<td valign="top">The sky seems to detract from the main subject here.</td>', 'The sky seems to detract from the main subject here.', '2004-03-25 15:28:37.000000', NULL, 1),
