(639601, 65925, 16095, '<td valign="top">i like this, great compositon and color</td>', 'i like this, great compositon and color', '2004-03-26 11:11:08.000000', NULL, 1),
(639603, 65127, 16095, '<td valign="top">beautiful and whimsical!</td>', 'beautiful and whimsical!', '2004-03-26 11:12:16.000000', NULL, 1),
(639604, 65737, 16095, '<td valign="top">this is so great-one of the few that really nails challenge</td>', 'this is so great-one of the few that really nails challenge', '2004-03-26 11:12:44.000000', NULL, 1),
(639607, 65590, 16095, '<td valign="top">awesome shot</td>', 'awesome shot', '2004-03-26 11:12:59.000000', NULL, 1),
(639608, 65884, 16095, '<td valign="top">breathtaking</td>', 'breathtaking', '2004-03-26 11:13:19.000000', NULL, 1),
(639613, 65834, 19010, '<td valign="top">Thouroghly enjoyable photo to look at. I expecialy love the way the Iris eplodes into colors and pattern resembling deep space photos.</td>', 'Thouroghly enjoyable photo to look at. I expecialy love the way the Iris eplodes into colors and pattern resembling deep space photos.', '2004-03-26 11:22:47.000000', NULL, 1),
(639648, 65127, 12733, '<td valign="top">The shot fits the magazine''s name, but it hardly looks like a magazine cover shot. The amount of background blur and the horizontal format hardly qualifies.</td>', 'The shot fits the magazine''s name, but it hardly looks like a magazine cover shot. The amount of background blur and the horizontal format hardly qualifies.', '2004-03-26 11:43:52.000000', NULL, 1),
(639649, 65482, 12733, '<td valign="top">I could picture this as a magazine cover, except that magazines almost universally use vertical format shots. I really like the colors and textures; it''s almost like a painting.</td>', 'I could picture this as a magazine cover, except that magazines almost universally use vertical format shots. I really like the colors and textures; it''s almost like a painting.', '2004-03-26 11:44:50.000000', NULL, 1),
(639651, 65776, 12733, '<td valign="top">This certainly fulfills the basics of a magazine cover - vertical format, a large space where type could go and very pretty colors and composition.</td>', 'This certainly fulfills the basics of a magazine cover - vertical format, a large space where type could go and very pretty colors and composition.', '2004-03-26 11:45:40.000000', NULL, 1),
(639652, 65602, 12733, '<td valign="top">Very nice shot; if it were cropped vertical it would be more blievable as a magazine cover.</td>', 'Very nice shot; if it were cropped vertical it would be more blievable as a magazine cover.', '2004-03-26 11:46:52.000000', NULL, 1),
(639653, 65553, 12733, '<td valign="top">I can almost taste it. Nice shot.</td>', 'I can almost taste it. Nice shot.', '2004-03-26 11:47:12.000000', NULL, 1),
(639656, 65927, 12733, '<td valign="top">Nice contrast between the weathered metal and the leaves. This has the elements of a magazine cover - vertical format, an area at the top where type could go without obscuring necessary detail and a good composition.</td>', 'Nice contrast between the weathered metal and the leaves. This has the elements of a magazine cover - vertical format, an area at the top where type could go without obscuring necessary detail and a good composition.', '2004-03-26 11:48:31.000000', NULL, 1),
(639662, 65636, 12733, '<td valign="top">A vertical crop would better suit the magazine cover format. I would take out the partial tree at the left, and you''d have a nice composition of parallels as well as a magazine style photo.</td>', 'A vertical crop would better suit the magazine cover format. I would take out the partial tree at the left, and you''d have a nice composition of parallels as well as a magazine style photo.', '2004-03-26 11:49:48.000000', NULL, 1),
(639664, 65900, 12733, '<td valign="top">Great timing, great shot, and the blurred out audience is a perfect place to put the magazine logo and type.</td>', 'Great timing, great shot, and the blurred out audience is a perfect place to put the magazine logo and type.', '2004-03-26 11:50:37.000000', NULL, 1),
(639665, 65452, 12733, '<td valign="top">A very pretty shot, but unless Water Gardening is a very unusual magazine, the cover should be vertical.</td>', 'A very pretty shot, but unless Water Gardening is a very unusual magazine, the cover should be vertical.', '2004-03-26 11:51:25.000000', NULL, 1),
(639671, 65749, 12733, '<td valign="top">Nice shot, and a good magazine cover, with a vertical format and space at the top that could carry type without spoiling the picture.</td>', 'Nice shot, and a good magazine cover, with a vertical format and space at the top that could carry type without spoiling the picture.', '2004-03-26 11:53:26.000000', NULL, 1),
(639675, 65124, 12733, '<td valign="top">I really like the picture, but unless Pacific Northwest Outdoors is a really different sort of magazine it would want a vertical format. The picture does have nice spaces for type - a necessity in a magazine cover - but the horizontal format just wouldn''t work.</td>', 'I really like the picture, but unless Pacific Northwest Outdoors is a really different sort of magazine it would want a vertical format. The picture does have nice spaces for type - a necessity in a magazine cover - but the horizontal format just wouldn''t work.', '2004-03-26 11:55:32.000000', NULL, 1),
(639679, 65760, 12733, '<td valign="top">I really like the shot, but it doesn''t exemplify the spirit of the magazine it purports to represent nor does it follow the basic vertical format of nearly all magazines published in this country.</td>', 'I really like the shot, but it doesn''t exemplify the spirit of the magazine it purports to represent nor does it follow the basic vertical format of nearly all magazines published in this country.', '2004-03-26 11:57:33.000000', NULL, 1),
(639681, 65859, 12733, '<td valign="top">Very nice scenic alo9ng with a great shot of a well-restored VW.</td>', 'Very nice scenic alo9ng with a great shot of a well-restored VW.', '2004-03-26 11:58:06.000000', NULL, 1),
(639683, 65408, 12733, '<td valign="top">Nice shot, and a good magazine cover, with a vertical format and space at the top that could carry type without spoiling the picture.</td>', 'Nice shot, and a good magazine cover, with a vertical format and space at the top that could carry type without spoiling the picture.', '2004-03-26 11:58:30.000000', NULL, 1),
(639685, 65460, 12733, '<td valign="top">A very pretty shot, but magazines are almost universally vertical, and should have a space where the logo and list of top stories could go without covering anything essential to the picture.</td>', 'A very pretty shot, but magazines are almost universally vertical, and should have a space where the logo and list of top stories could go without covering anything essential to the picture.', '2004-03-26 11:59:27.000000', NULL, 1),
