(639727, 65676, 12733, '<td valign="top">A beautiful photo, but magazines are almost always vertical in format. This shot does have the other requirement-a place where type could go without spoiling it.</td>', 'A beautiful photo, but magazines are almost always vertical in format. This shot does have the other requirement-a place where type could go without spoiling it.', '2004-03-26 12:16:07.000000', NULL, 1),
(639728, 65777, 12733, '<td valign="top">Great action, nice colors and composition. This shot meets the challenge - it''s vertical and has space at the top that could be blended with type without spoiling the photo''s impact.</td>', 'Great action, nice colors and composition. This shot meets the challenge - it''s vertical and has space at the top that could be blended with type without spoiling the photo''s impact.', '2004-03-26 12:17:37.000000', NULL, 1),
