(639736, 65911, 12733, '<td valign="top">Nice shot, and a good magazine cover, with a vertical format and space at the top that could carry type without spoiling the picture. I really like the silhouette effect.</td>', 'Nice shot, and a good magazine cover, with a vertical format and space at the top that could carry type without spoiling the picture. I really like the silhouette effect.', '2004-03-26 12:22:39.000000', NULL, 1),
(639737, 65401, 12733, '<td valign="top">Nice shot, and a good magazine cover, with a vertical format and space at the top that could carry type without spoiling the picture.</td>', 'Nice shot, and a good magazine cover, with a vertical format and space at the top that could carry type without spoiling the picture.', '2004-03-26 12:22:53.000000', NULL, 1),
