(639741, 65928, 12733, '<td valign="top">A beautiful picture, but magazines are almost always vertical format. If this were cropped right to the bird, with the open water at the top it would be perfect - that water would be a great background for the type and the picture would stand out well.</td>', 'A beautiful picture, but magazines are almost always vertical format. If this were cropped right to the bird, with the open water at the top it would be perfect - that water would be a great background for the type and the picture would stand out well.', '2004-03-26 12:25:31.000000', NULL, 1),
(639743, 65851, 12733, '<td valign="top">Looks yummy and fulfills the requirements of a magazine cover - vertical format and space within the picture where type could be overlaid.</td>', 'Looks yummy and fulfills the requirements of a magazine cover - vertical format and space within the picture where type could be overlaid.', '2004-03-26 12:26:48.000000', NULL, 1),
(639745, 65893, 12733, '<td valign="top">A great shot, and it would make a great magazine cover if it were vertical - that''s the format of almost all magazines published in the United States.</td>', 'A great shot, and it would make a great magazine cover if it were vertical - that''s the format of almost all magazines published in the United States.', '2004-03-26 12:27:54.000000', NULL, 1),
